/* Blush Tiny Blossoms — site script. Data comes from /assets/data.js (window.BLUSH), generated by build.py. */
(function () {
  const { shop: SHOP, looks: LOOKS } = window.BLUSH;
  const ROOT = new URL("..", document.currentScript.src).href; // site root, wherever the site is hosted
  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => [...r.querySelectorAll(s)];
  const esc = s => String(s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  const fullName = l => l.name + (l.variant ? " · " + l.variant : "");
  const money = n => SHOP.currency + Number(n).toLocaleString("en-IN");
  const priceOf = (l, size) => (l.priceBySize && size ? l.priceBySize[size] : null) || null;
  const fromPrice = l => (l.priceBySize ? "From " + money(Math.min(...Object.values(l.priceBySize))) : "Price on request");
  const priceText = (l, size) => (priceOf(l, size) ? money(priceOf(l, size)) : fromPrice(l));
  const igDM = "https://ig.me/m/" + SHOP.instagram;
  /* Meta Pixel shop events (only if the pixel loaded) */
  const pixel = (ev, data, opts) => { try { if (window.fbq) window.fbq("track", ev, data || {}, opts || {}); } catch (e) {} };
  const shipFor = sub => (sub >= SHOP.freeAbove ? 0 : SHOP.shipFee);
  const waLink = text => "https://wa.me/" + SHOP.whatsapp + (text ? "?text=" + encodeURIComponent(text) : "");

  /* ── Bag: the one place that knows how items are stored. Swap this for a real cart API when the store opens. ── */
  const KEY = "blush.bag.v1";
  let memory = [];
  const Bag = {
    read() {
      try { const v = JSON.parse(localStorage.getItem(KEY) || "[]"); memory = Array.isArray(v) ? v.filter(i => LOOKS[i.id]) : []; } catch (e) {}
      return memory;
    },
    write(items) {
      memory = items;
      try { localStorage.setItem(KEY, JSON.stringify(items)); } catch (e) {}
      paintCount();
    },
    add(id, size) {
      const items = Bag.read();
      const hit = items.find(i => i.id === id && i.size === size);
      if (hit) hit.qty = Math.min(9, hit.qty + 1); else items.push({ id, size, qty: 1 });
      Bag.write(items);
    },
    count() { return Bag.read().reduce((n, i) => n + i.qty, 0); },
    message(items) {
      const lines = items.map(i => { const p = priceOf(LOOKS[i.id], i.size); return "• " + fullName(LOOKS[i.id]) + (i.size ? ", size " + i.size : "") + (i.qty > 1 ? " × " + i.qty : "") + (p ? " (" + money(p) + (i.qty > 1 ? " each" : "") + ")" : ""); });
      const sub = Bag.subtotal(items);
      return "Hi Blush! I'd like to order:\n" + lines.join("\n") + (sub !== null ? "\nTotal: " + money(sub) : "") + "\nPlease confirm availability and delivery.";
    },
    subtotal(items) { return items.every(i => priceOf(LOOKS[i.id], i.size)) ? items.reduce((n, i) => n + priceOf(LOOKS[i.id], i.size) * i.qty, 0) : null; }
  };
  function paintCount() {
    const n = memory.reduce((a, i) => a + i.qty, 0);
    $$(".bag-count").forEach(el => { el.textContent = n; el.dataset.n = n; });
    $$(".bag-link").forEach(el => el.setAttribute("aria-label", "Enquiry bag, " + n + (n === 1 ? " item" : " items")));
  }
  Bag.read(); paintCount();

  async function copy(text, btn, fallbackEl) {
    try { await navigator.clipboard.writeText(text); btn.textContent = "Copied"; }
    catch (e) {
      if (fallbackEl) { const r = document.createRange(); r.selectNodeContents(fallbackEl); const s = getSelection(); s.removeAllRanges(); s.addRange(r); }
      btn.textContent = "Selected, now copy";
    }
    setTimeout(() => (btn.textContent = btn.dataset.label || "Copy message"), 2400);
  }

  /* ── Header ── */
  const menuBtn = $(".menu-btn"), menu = $("#menu");
  if (menuBtn) {
    menuBtn.addEventListener("click", () => {
      const open = menu.classList.toggle("open");
      menuBtn.setAttribute("aria-expanded", open);
    });
    document.addEventListener("keydown", e => { if (e.key === "Escape") { menu.classList.remove("open"); menuBtn.setAttribute("aria-expanded", "false"); } });
  }
  if (SHOP.whatsapp) $$("[data-wa]").forEach(el => { el.hidden = false; const a = el.matches("a") ? el : $("a", el); if (a && !a.dataset.msg) a.href = waLink(""); });

  /* ── Collection filters ── */
  const filters = $("#filters");
  if (filters) {
    const cards = $$("#grid .card");
    const setFilter = (k, push) => {
      if (!$$(".filter", filters).some(b => b.dataset.key === k)) k = "all";
      $$(".filter", filters).forEach(b => b.setAttribute("aria-pressed", b.dataset.key === k));
      cards.forEach(c => (c.hidden = !(k === "all" || c.dataset.cat.split(" ").includes(k))));
      const n = cards.filter(c => !c.hidden).length, cnt = $("#count"); if (cnt) cnt.textContent = n + (n === 1 ? " look" : " looks");
      if (push) history.replaceState(null, "", k === "all" ? location.pathname : "?show=" + k);
    };
    filters.addEventListener("click", e => { const b = e.target.closest(".filter"); if (b) setFilter(b.dataset.key, true); });
    setFilter(new URLSearchParams(location.search).get("show") || "all", false);
  }

  /* ── Look page ── */
  const lookEl = $("[data-look]");
  if (lookEl) {
    const l = LOOKS[lookEl.dataset.look];
    let size = null;
    const msgEl = $("#look-msg"), buy = $("#look-buy"), added = $("#look-added"), sizes = $("#look-sizes"), chosen = $("#size-chosen");
    const mrpOf = s => (l.mrpBySize && s ? l.mrpBySize[s] : null);
    const message = () => "Hi Blush! I'd like to order " + fullName(l) + (size ? " in size " + size : "") + (priceOf(l, size) ? " (" + money(priceOf(l, size)) + ")" : "") + ".\n" + location.href.split("?")[0] + "\nPlease confirm availability" + (l.priceBySize ? "." : " and share the price.");
    const refresh = () => {
      if (msgEl) msgEl.textContent = message();
      if (SHOP.whatsapp && buy) buy.href = waLink(message());
    };
    const paintPrice = () => {
      $("#look-price").textContent = priceText(l, size);
      const m = $("#look-mrp"), sv = $("#look-save");
      const mp = size ? mrpOf(size) : (l.mrpBySize ? Math.min(...Object.values(l.mrpBySize)) : null);
      const pp = size ? priceOf(l, size) : (l.priceBySize ? Math.min(...Object.values(l.priceBySize)) : null);
      if (m) { m.hidden = !(mp && pp && mp > pp); if (mp) m.textContent = money(mp); }
      if (sv && mp && pp) sv.textContent = "Sale · Save " + Math.round(100 * (1 - pp / mp)) + "%";
    };
    if (sizes) sizes.addEventListener("click", e => {
      const b = e.target.closest("button"); if (!b || b.disabled) return;
      size = b.textContent; $$("button", sizes).forEach(x => x.setAttribute("aria-pressed", x === b));
      if (chosen) chosen.textContent = size;
      added.textContent = ""; paintPrice(); refresh();
    });
    const needSize = () => { if (l.sizes.length && !size) { added.textContent = "Please choose a size first."; sizes.querySelector("button:not(:disabled)")?.focus(); return true; } return false; };
    pixel("ViewContent", { content_ids: [l.id], content_name: fullName(l), content_type: "product", currency: "INR", value: l.priceBySize ? Math.min(...Object.values(l.priceBySize)) : 0 });
    const trackAdd = () => pixel("AddToCart", { content_ids: [l.id], content_name: fullName(l), content_type: "product", currency: "INR", value: priceOf(l, size) || 0, contents: [{ id: l.id, quantity: 1 }] });
    $("#look-add").addEventListener("click", () => {
      if (needSize()) return;
      Bag.add(l.id, size); trackAdd();
      added.innerHTML = "Added to your bag. <a href=\"" + ROOT + "bag\">View bag</a>";
    });
    if (buy && SHOP.checkoutApi) buy.addEventListener("click", () => { if (needSize()) return; Bag.add(l.id, size); trackAdd(); location.href = ROOT + "checkout"; });
    else if (buy && SHOP.whatsapp) buy.addEventListener("click", e => { if (needSize()) e.preventDefault(); });
    const lc = $("#look-copy"); if (lc) lc.addEventListener("click", e => copy(message(), e.currentTarget, msgEl));
    const cl = $("#copy-link");
    if (cl) cl.addEventListener("click", async () => {
      const out = $("#link-copied");
      try { await navigator.clipboard.writeText(cl.dataset.url); out.textContent = "Link copied"; } catch (e) { out.textContent = cl.dataset.url; }
      setTimeout(() => (out.textContent = ""), 2600);
    });
    refresh();

    /* gallery: swipe/scroll track, thumbnails, arrows, lightbox */
    const track = $("#track");
    if (track) {
      const slides = $$(".slide", track), thumbs = $$(".thumbs button");
      let cur = 0;
      const go = i => { cur = (i + slides.length) % slides.length; track.scrollTo({ left: track.clientWidth * cur }); };
      const mark = () => {
        cur = Math.round(track.scrollLeft / Math.max(1, track.clientWidth));
        thumbs.forEach((t, i) => t.setAttribute("aria-selected", i === cur));
      };
      track.addEventListener("scroll", () => requestAnimationFrame(mark), { passive: true });
      thumbs.forEach((t, i) => t.addEventListener("click", () => go(i)));
      $$(".stage .nav-arrow").forEach(b => b.addEventListener("click", () => go(cur + (b.classList.contains("next") ? 1 : -1))));
      const lb = $("#lightbox"), lbImg = $("#lb-img");
      const full = i => { const im = $("img", slides[i]); return im.srcset.split(",").map(x => x.trim().split(" ")[0]).pop(); };
      const show = i => { cur = (i + slides.length) % slides.length; lbImg.src = full(cur); lbImg.alt = $("img", slides[cur]).alt; };
      if (lb && lb.showModal) {
        slides.forEach((s, i) => s.addEventListener("click", () => { show(i); lb.showModal(); }));
        $$("[data-lb]", lb).forEach(b => b.addEventListener("click", () => show(cur + +b.dataset.lb)));
        lbImg.addEventListener("click", () => lb.close());
        lb.addEventListener("close", () => go(cur));
        lb.addEventListener("keydown", e => { if (e.key === "ArrowRight") show(cur + 1); if (e.key === "ArrowLeft") show(cur - 1); });
      }
    }
  }

  /* size guide dialog + cm/in switch (look pages and the size guide page) */
  $$("[data-open]").forEach(b => b.addEventListener("click", () => { const d = document.getElementById(b.dataset.open); if (d && d.showModal) d.showModal(); }));
  $$("dialog").forEach(d => d.addEventListener("click", e => { if (e.target === d) d.close(); }));
  $$(".chart").forEach(c => c.addEventListener("click", e => {
    const b = e.target.closest("[data-u]"); if (!b) return;
    $$(".chart").forEach(x => { x.dataset.unit = b.dataset.u; $$("[data-u]", x).forEach(y => y.setAttribute("aria-pressed", y.dataset.u === b.dataset.u)); });
  }));

  /* "You may also like" rail arrows */
  const rail = $("#rail");
  if (rail) $$("[data-rail]").forEach(b => b.addEventListener("click", () => rail.scrollBy({ left: +b.dataset.rail * rail.clientWidth * 0.8 })));

  /* FAQ: open the question group that a link points to, highlight the section in view */
  const faqNav = $(".faq-nav:not(.toc)");
  if (faqNav) {
    const links = $$("a", faqNav);
    const io = new IntersectionObserver(es => es.forEach(en => { if (en.isIntersecting) links.forEach(a => a.classList.toggle("on", a.hash === "#" + en.target.id)); }), { rootMargin: "-30% 0px -60% 0px" });
    $$(".faq-sec").forEach(s => io.observe(s));
  }

  /* ── Bag page ── */
  const bagRoot = $("#bag-root");
  if (bagRoot) {
    const render = () => {
      const items = Bag.read();
      if (!items.length) {
        bagRoot.innerHTML = '<div class="empty"><svg class="blossom" viewBox="0 0 24 24" fill="currentColor" style="color:var(--rose)" aria-hidden="true"><circle cx="12" cy="5.5" r="3.4"/><circle cx="18.2" cy="10" r="3.4"/><circle cx="15.8" cy="17.2" r="3.4"/><circle cx="8.2" cy="17.2" r="3.4"/><circle cx="5.8" cy="10" r="3.4"/></svg><p class="lede">Your enquiry bag is empty.</p><a class="btn" href="' + ROOT + 'collection">View the collection</a></div>';
        return;
      }
      const msg = Bag.message(items), sub = Bag.subtotal(items), n = items.reduce((a, i) => a + i.qty, 0);
      const storeReady = !!SHOP.checkoutApi && sub !== null;
      bagRoot.innerHTML = '<div class="bag"><div class="bag-items">' + items.map((i, x) => {
        const l = LOOKS[i.id];
        return '<div class="bag-item"><a class="arch" href="' + ROOT + 'looks/' + l.id + '"><img src="' + ROOT + 'img/' + l.id + '-480.webp" alt="" style="object-position:' + l.pos + '"></a>' +
          '<div><h3><a href="' + ROOT + 'looks/' + l.id + '">' + esc(fullName(l)) + '</a></h3><p class="meta">' + (i.size ? "Size " + esc(i.size) : "Size on request") + '</p><p class="price">' + priceText(l, i.size) + '</p></div>' +
          '<div class="bag-ctl"><div class="qty"><button type="button" data-act="dec" data-x="' + x + '" aria-label="One fewer">–</button><span aria-live="polite">' + i.qty + '</span><button type="button" data-act="inc" data-x="' + x + '" aria-label="One more">+</button></div>' +
          '<button type="button" class="linkbtn" data-act="del" data-x="' + x + '">Remove</button></div></div>';
      }).join("") + '</div>' +
        '<aside class="preview"><span class="eyebrow">Your enquiry</span>' +
        '<div class="sum-row"><span>Pieces</span><b>' + n + '</b></div>' +
        '<div class="sum-row"><span>' + (sub !== null ? "Subtotal" : "Price") + '</span><b>' + (sub !== null ? money(sub) : "Confirmed on message") + '</b></div>' +
        (storeReady ? '<div class="sum-row"><span>Delivery</span><b>' + (shipFor(sub) ? money(shipFor(sub)) : "Free") + '</b></div>' : "") +
        '<div class="msg" id="bag-msg">' + esc(msg) + '</div>' +
        '<div class="dlg-cta">' +
        (storeReady ? '<a class="btn" href="' + ROOT + 'checkout">Checkout · ' + money(sub + shipFor(sub)) + '</a>' : "") +
        (SHOP.whatsapp ? '<a class="btn' + (storeReady ? " ghost" : "") + '" href="' + waLink(msg) + '" target="_blank" rel="noopener">Send on WhatsApp</a>' : "") +
        '<button class="btn' + (storeReady || SHOP.whatsapp ? " ghost" : "") + '" type="button" id="bag-copy" data-label="Copy message">Copy message</button>' +
        '<a class="btn ghost" href="' + igDM + '" target="_blank" rel="noopener">Open Instagram chat</a>' +
        '</div><p class="hint">' + (SHOP.whatsapp ? "WhatsApp opens with the message ready. For Instagram, copy the message and paste it in our chat." : "Copy the message, then paste it in our Instagram chat.") + ' We reply to confirm availability and delivery.</p></aside></div>';
    };
    bagRoot.addEventListener("click", e => {
      const b = e.target.closest("[data-act]");
      if (b) {
        const items = Bag.read(), i = items[+b.dataset.x]; if (!i) return;
        if (b.dataset.act === "inc") i.qty = Math.min(9, i.qty + 1);
        if (b.dataset.act === "dec") i.qty -= 1;
        if (b.dataset.act === "del" || i.qty < 1) items.splice(+b.dataset.x, 1);
        Bag.write(items); render(); return;
      }
      if (e.target.id === "bag-copy") copy(Bag.message(Bag.read()), e.target, $("#bag-msg"));
    });
    render();
  }


  /* ── Checkout (Cashfree) ── */
  const coRoot = $("#checkout-root");
  if (coRoot) {
    const api = coRoot.dataset.api.replace(/\/$/, "");
    const form = $("#co-form"), err = $("#co-err"), pay = $("#co-pay");
    const items = Bag.read();
    const KEY_C = "blush.customer.v1";
    if (!items.length) { location.replace(ROOT + "bag"); return; }
    const sub = Bag.subtotal(items);
    if (sub === null) { err.textContent = "One of the pieces in your bag has no price yet. Please send your bag to us on WhatsApp instead."; pay.disabled = true; }
    const ship = sub === null ? 0 : shipFor(sub);
    $("#co-items").innerHTML = items.map(i => { const l = LOOKS[i.id]; return '<div class="co-item"><img src="' + ROOT + 'img/' + l.id + '-480.webp" alt="" style="object-position:' + l.pos + '"><div><b>' + esc(fullName(l)) + '</b><span>' + (i.size ? "Size " + esc(i.size) : "") + (i.qty > 1 ? " · × " + i.qty : "") + '</span></div><span>' + (priceOf(l, i.size) ? money(priceOf(l, i.size) * i.qty) : "–") + '</span></div>'; }).join("");
    $("#co-sub").textContent = sub === null ? "–" : money(sub);
    $("#co-ship").textContent = sub === null ? "–" : ship ? money(ship) : "Free";
    /* welcome offer: the checkout service says whether this mobile / email has an unused offer; it also sets the real amount */
    let disc = 0, offerSeq = 0;
    const paint = () => {
      $("#co-disc-row").hidden = !disc; $("#co-disc").textContent = "– " + money(disc);
      $("#co-total").textContent = sub === null ? "–" : money(sub - disc + ship);
      if (sub !== null && !pay.disabled) pay.textContent = "Pay " + money(sub - disc + ship) + " securely";
    };
    const phoneOf = v => String(v || "").replace(/\D/g, "").replace(/^(91|0)(?=\d{10}$)/, "");
    const checkOffer = async () => {
      if (!SHOP.welcomePct || sub === null) return;
      const phone = phoneOf(form.phone.value), email = form.email.value.trim().toLowerCase(), seq = ++offerSeq;
      if (!/^[6-9]\d{9}$/.test(phone) && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) { disc = 0; paint(); return; }
      try {
        const r = await fetch(api + "/offer", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ phone, email }) });
        const d = await r.json().catch(() => ({}));
        if (seq !== offerSeq) return;
        disc = r.ok && d.eligible ? Math.round(sub * (d.pct || 0) / 100) : 0;
      } catch (e) { if (seq === offerSeq) disc = 0; }
      paint();
    };
    let offerTimer; const offerSoon = () => { clearTimeout(offerTimer); offerTimer = setTimeout(checkOffer, 500); };
    paint();
    pixel("InitiateCheckout", { content_ids: items.map(i => i.id), content_type: "product", currency: "INR", value: sub === null ? 0 : sub + ship, num_items: items.reduce((n, i) => n + i.qty, 0) });
    try { const saved = JSON.parse(localStorage.getItem(KEY_C) || "{}"); Object.keys(saved).forEach(k => { if (form[k] && !form[k].value) form[k].value = saved[k]; }); } catch (e) {}
    form.phone.addEventListener("input", offerSoon); form.email.addEventListener("input", offerSoon); checkOffer();
    form.addEventListener("submit", async e => {
      e.preventDefault(); err.textContent = "";
      const c = Object.fromEntries(new FormData(form));
      const miss = ["name", "phone", "address1", "city", "pin", "state"].find(k => !String(c[k] || "").trim());
      if (miss) { err.textContent = "Please fill in " + form[miss].closest("label").firstChild.textContent.trim().toLowerCase() + "."; form[miss].focus(); return; }
      if (!/^[6-9]\d{9}$/.test(c.phone.replace(/\D/g, "").replace(/^(91|0)(?=\d{10}$)/, ""))) { err.textContent = "Please enter a 10-digit mobile number."; form.phone.focus(); return; }
      if (!/^[1-9]\d{5}$/.test(c.pin.trim())) { err.textContent = "Please enter a 6-digit PIN code."; form.pin.focus(); return; }
      try { const keep = { ...c }; delete keep.note; localStorage.setItem(KEY_C, JSON.stringify(keep)); } catch (e) {}
      pay.disabled = true; const label = pay.textContent; pay.textContent = "Opening secure payment…";
      try {
        const r = await fetch(api + "/create-order", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ items: items.map(i => ({ id: i.id, size: i.size, qty: i.qty })), customer: c }) });
        const d = await r.json().catch(() => ({}));
        if (!r.ok || !d.payment_session_id) throw new Error(d.error || "Could not start the payment. Please try again.");
        try { sessionStorage.setItem("blush.lastOrder", d.order_id); } catch (e) {}
        if (typeof d.discount === "number") { disc = d.discount; $("#co-disc-row").hidden = !disc; $("#co-disc").textContent = "– " + money(disc); $("#co-total").textContent = money(d.amount); }
        if (typeof Cashfree !== "function") throw new Error("The payment window could not load. Please check your connection and try again.");
        Cashfree({ mode: d.mode === "production" ? "production" : "sandbox" }).checkout({ paymentSessionId: d.payment_session_id, redirectTarget: "_self" });
      } catch (x) { err.textContent = x.message; pay.disabled = false; pay.textContent = label; }
    });
  }

  /* ── Welcome offer pop-up: first visit only. Details are saved through the checkout service into the Google Sheet. ── */
  const wl = $("#welcome");
  if (wl && wl.showModal && SHOP.welcomePct && !coRoot && !$("#order-root")) {
    const KEY_W = "blush.welcome.v1";
    let state = null; try { state = localStorage.getItem(KEY_W); } catch (e) { state = "off"; }
    const remember = v => { try { localStorage.setItem(KEY_W, v); } catch (e) {} };
    const f = $("#wl-form"), werr = $("#wl-err"), go = $("#wl-go");
    if (!state) setTimeout(() => { if (!document.querySelector("dialog[open]")) { wl.showModal(); remember("seen"); } }, 3500);
    $("#wl-close").addEventListener("click", () => wl.close());
    f.addEventListener("submit", async e => {
      e.preventDefault(); werr.textContent = "";
      const name = f.name.value.trim(), phone = f.phone.value.replace(/\D/g, "").replace(/^(91|0)(?=\d{10}$)/, ""), email = f.email.value.trim();
      if (name.length < 2) { werr.textContent = "Please enter your name."; f.name.focus(); return; }
      if (!/^[6-9]\d{9}$/.test(phone)) { werr.textContent = "Please enter a 10-digit mobile number."; f.phone.focus(); return; }
      if (email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) { werr.textContent = "Please check your email address."; f.email.focus(); return; }
      go.disabled = true; const label = go.textContent; go.textContent = "Saving…";
      try {
        const r = await fetch(wl.dataset.api.replace(/\/$/, "") + "/signup", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name, phone, email, page: location.pathname }) });
        const d = await r.json().catch(() => ({}));
        if (!r.ok) throw new Error(d.error || "We could not save that just now. Please try again.");
        remember("joined");
        try { const c = JSON.parse(localStorage.getItem("blush.customer.v1") || "{}"); localStorage.setItem("blush.customer.v1", JSON.stringify({ ...c, name: c.name || name, phone: c.phone || phone, email: c.email || email })); } catch (x) {}
        pixel("Lead", { content_name: "Welcome offer" });
        f.hidden = true;
        $("#wl-title").innerHTML = d.used ? "Welcome <em>back</em>" : "You’re <em>in</em>";
        $("#wl-text").textContent = d.used ? "This mobile number or email has already used its welcome offer. Thank you for shopping with us." : SHOP.welcomePct + "% comes off your first order at checkout. Use the same mobile number" + (email ? " or email" : "") + " and it applies by itself.";
        $("#wl-text").insertAdjacentHTML("afterend", '<a class="btn" href="' + ROOT + 'collection">View the collection</a>');
      } catch (x) { werr.textContent = x.message; go.disabled = false; go.textContent = label; }
    });
  }

  /* ── Order confirmation (return from Cashfree) ── */
  const ordRoot = $("#order-root");
  if (ordRoot) {
    const api = ordRoot.dataset.api.replace(/\/$/, "");
    const id = new URLSearchParams(location.search).get("order_id") || (() => { try { return sessionStorage.getItem("blush.lastOrder"); } catch (e) { return null; } })();
    const title = $("#ord-title"), text = $("#ord-text"), box = $("#ord-box"), cta = $("#ord-cta"), eb = $("#ord-eyebrow");
    const done = (t, p, actions) => { title.innerHTML = t; text.textContent = p; cta.innerHTML = actions; cta.hidden = false; };
    const waBtn = msg => (SHOP.whatsapp ? '<a class="btn ghost" href="' + waLink(msg) + '" target="_blank" rel="noopener">WhatsApp us</a>' : "");
    const check = async (n) => {
      if (!id || !api) { done("We couldn’t find <em>that order</em>", "If you were charged, message us with your payment details and we will sort it out.", '<a class="btn" href="' + ROOT + 'collection">Back to the collection</a>' + waBtn("Hi Blush! I need help with a payment.")); return; }
      try {
        const r = await fetch(api + "/order-status?order_id=" + encodeURIComponent(id));
        const d = await r.json();
        if (r.status === 404 || r.status === 400) { done("We couldn’t find <em>that order</em>", "If you were charged, message us with your payment details and we will sort it out.", '<a class="btn" href="' + ROOT + 'collection">Back to the collection</a>' + waBtn("Hi Blush! I need help with order " + id + ".")); return; }
        if (!r.ok) throw new Error(d.error);
        if (d.paid) {
          const items = Bag.read();
          let seen = false; try { seen = localStorage.getItem("blush.px." + d.order_id) === "1"; localStorage.setItem("blush.px." + d.order_id, "1"); } catch (e) {}
          if (!seen) pixel("Purchase", { value: Number(d.amount), currency: "INR", content_type: "product", content_ids: items.map(i => i.id), num_items: items.reduce((n, i) => n + i.qty, 0) }, { eventID: d.order_id });
          Bag.write([]);
          eb.textContent = "Order " + d.order_id;
          box.innerHTML = '<div class="sum-row"><span>Items</span><b>' + esc(d.items) + '</b></div><div class="sum-row total"><span>Paid</span><b>' + money(d.amount) + '</b></div>'; box.hidden = false;
          done("Thank you" + (d.name ? ", " + esc(d.name.split(" ")[0]) : "") + ". <em>It’s yours.</em>", "Your payment is confirmed. We’ll message you on WhatsApp when your order is dispatched.",
            '<a class="btn" href="' + ROOT + 'collection">Keep browsing</a>' + waBtn("Hi Blush! I just placed order " + d.order_id + "."));
        } else if (d.status === "ACTIVE" && n < 4) { setTimeout(() => check(n + 1), 2500); }
        else {
          done("Payment <em>not completed</em>", "No money was taken for this order, or it is still processing. Your bag is saved, so you can try again.",
            '<a class="btn" href="' + ROOT + 'checkout">Try again</a>' + waBtn("Hi Blush! My payment for order " + id + " didn’t go through."));
        }
      } catch (x) { done("We couldn’t check <em>your payment</em>", "Please refresh in a moment. If money was taken, message us with order " + id + " and we will confirm it.", '<a class="btn" href="">Refresh</a>' + waBtn("Hi Blush! Please check my order " + id + ".")); }
    };
    check(0);
  }

  /* ── Contact composer ── */
  const form = $("#enquiry");
  if (form) {
    const out = $("#enq-msg"), wa = $("#enq-wa");
    const pre = new URLSearchParams(location.search).get("look");
    if (pre && LOOKS[pre]) form.look.value = pre;
    const message = () => {
      const f = form, l = LOOKS[f.look.value], parts = [];
      parts.push("Hi Blush!" + (f.name.value.trim() ? " This is " + f.name.value.trim() + "." : ""));
      parts.push(l ? "I'd like to enquire about " + fullName(l) + (f.size.value ? " in size " + f.size.value : "") + "." : "I'd like to enquire about your festive collection.");
      if (f.age.value.trim()) parts.push("My child is " + f.age.value.trim() + ".");
      if (f.date.value) parts.push("We need it by " + new Date(f.date.value + "T00:00").toLocaleDateString("en-IN", { day: "numeric", month: "long", year: "numeric" }) + ".");
      if (f.note.value.trim()) parts.push(f.note.value.trim());
      if (l && priceOf(l, f.size.value)) parts.push("The price shown is " + money(priceOf(l, f.size.value)) + ".");
      parts.push("Please confirm availability.");
      return parts.join(" ");
    };
    const refresh = () => { out.textContent = message(); if (SHOP.whatsapp) { wa.hidden = false; wa.href = waLink(message()); } };
    form.addEventListener("input", refresh);
    form.addEventListener("submit", e => e.preventDefault());
    $("#enq-copy").addEventListener("click", e => copy(message(), e.currentTarget, out));
    refresh();
  }
})();
